"use client";

import { useMemo } from "react";
import { Box, Chip, Stack, Typography } from "@mui/material";
import type { LabelDocument } from "@easyprint/shared/template/document";
import type { PreviewPayload } from "@easyprint/shared/template/render";
import { LabelPreviewSurface } from "../editor/label-preview-surface";

const PREVIEW_MAX_WIDTH = 340;
const PREVIEW_MAX_HEIGHT = 420;

export function ModelPrintPreview({
  document,
  previewPayload,
  loading,
  quantity
}: {
  document: LabelDocument | null;
  previewPayload: PreviewPayload;
  loading: boolean;
  quantity: number;
}) {
  const previewScale = useMemo(() => {
    if (!document) {
      return 1;
    }

    return Math.min(
      5.5,
      PREVIEW_MAX_WIDTH / Math.max(document.document.width, 1),
      PREVIEW_MAX_HEIGHT / Math.max(document.document.height, 1)
    );
  }, [document]);

  return (
    <Box
      sx={{
        display: "grid",
        gridTemplateRows: "auto minmax(0, 1fr)",
        gap: 2,
        minHeight: 0,
        pl: { md: 1 }
      }}
    >
      <Stack spacing={1}>
        <Typography variant="overline" color="text.secondary">
          Preview oficial do modelo
        </Typography>
        <Typography variant="h6">Etiqueta pronta para impressao</Typography>
        <Stack direction="row" spacing={1} useFlexGap sx={{ flexWrap: "wrap" }}>
          <Chip size="small" variant="outlined" label="Mesmo renderer do preview e da impressao" />
          <Chip
            size="small"
            color="primary"
            variant="outlined"
            label={`${quantity} etiqueta${quantity > 1 ? "s" : ""}`}
          />
        </Stack>
        {document ? (
          <Typography variant="body2" color="text.secondary">
            {document.document.width} x {document.document.height} {document.document.unit}
          </Typography>
        ) : null}
      </Stack>

      <Box
        sx={{
          minHeight: 360,
          display: "grid",
          placeItems: "center",
          borderRadius: 3,
          border: "1px dashed rgba(15, 23, 42, 0.12)",
          background:
            "linear-gradient(180deg, rgba(248,250,252,0.92), rgba(241,245,249,0.92))",
          p: 2
        }}
      >
        {loading ? (
          <Typography color="text.secondary">Carregando modelo...</Typography>
        ) : document ? (
          <Box
            sx={{
              display: "grid",
              placeItems: "center",
              width: "100%"
            }}
          >
            <LabelPreviewSurface
              document={document}
              previewPayload={previewPayload}
              scale={previewScale}
              preset="modal"
            />
          </Box>
        ) : (
          <Typography color="text.secondary">Selecione um modelo para visualizar.</Typography>
        )}
      </Box>
    </Box>
  );
}
