"use client";

import type { ReactNode } from "react";
import {
  Box,
  IconButton,
  Stack,
  Tooltip,
  Typography
} from "@mui/material";
import LockOpenRoundedIcon from "@mui/icons-material/LockOpenRounded";
import LockRoundedIcon from "@mui/icons-material/LockRounded";

export function UnlockableField({
  label,
  labelFor,
  locked,
  onToggle,
  lockedHint,
  unlockedHint,
  children
}: {
  label: string;
  labelFor?: string;
  locked: boolean;
  onToggle: () => void;
  lockedHint: string;
  unlockedHint: string;
  children: ReactNode;
}) {
  return (
    <Box
      sx={{
        display: "grid",
        gap: 1,
        p: 1.5,
        borderRadius: 2.5,
        backgroundColor: locked ? "rgba(248,250,252,0.92)" : "rgba(15,118,110,0.04)",
        border: locked
          ? "1px solid rgba(15, 23, 42, 0.08)"
          : "1px solid rgba(15, 118, 110, 0.16)"
      }}
    >
      <Stack
        direction="row"
        spacing={1.5}
        sx={{ justifyContent: "space-between", alignItems: "flex-start" }}
      >
        <Box>
          <Typography
            component="label"
            htmlFor={labelFor}
            variant="subtitle2"
            sx={{ display: "block" }}
          >
            {label}
          </Typography>
          <Typography variant="caption" color="text.secondary">
            {locked ? lockedHint : unlockedHint}
          </Typography>
        </Box>

        <Tooltip title={locked ? `Desbloquear ${label}` : `Bloquear ${label}`}>
          <IconButton
            size="small"
            color={locked ? "default" : "primary"}
            onClick={onToggle}
            aria-pressed={!locked}
            aria-label={locked ? `Editar ${label}` : `Fixar ${label}`}
            sx={{
              border: "1px solid rgba(15, 23, 42, 0.08)",
              bgcolor: "#fff"
            }}
          >
            {locked ? <LockRoundedIcon fontSize="small" /> : <LockOpenRoundedIcon fontSize="small" />}
          </IconButton>
        </Tooltip>
      </Stack>

      {children}
    </Box>
  );
}
