import type { LabelDocument } from "@easyprint/shared/template/document";
import type { PreviewPayload } from "@easyprint/shared/template/render";
import { resolveFieldPreviewValue } from "@easyprint/shared/template/render";
import {
  normalizeBarcodeText,
  validateBarcodeValue,
  validateQrCodeValue
} from "@easyprint/shared/template/barcode";

export function getScannableValidationErrors(
  document: LabelDocument,
  previewPayload: PreviewPayload
) {
  return document.elements.flatMap((element) => {
    if (element.type === "barcode") {
      const rawValue = element.bindingKey
        ? String(resolveFieldPreviewValue(document, element.bindingKey, previewPayload) || element.value)
        : element.value;
      const value = normalizeBarcodeText(element.format, rawValue);
      const validation = validateBarcodeValue(element.format, value);

      return validation.valid
        ? []
        : [`${element.name}: ${validation.message ?? "codigo de barras invalido"}`];
    }

    if (element.type === "qrcode") {
      const validation = validateQrCodeValue(element.value);
      return validation.valid
        ? []
        : [`${element.name}: ${validation.message ?? "QR Code invalido"}`];
    }

    return [];
  });
}
