import { Chip, type ChipProps } from "@mui/material";

const statusMap: Record<string, ChipProps["color"]> = {
  DRAFT: "default",
  IN_REVIEW: "warning",
  APPROVED: "success",
  PUBLISHED: "primary",
  ARCHIVED: "default",
  draft: "default",
  in_review: "warning",
  approved: "success",
  published: "primary",
  archived: "default",
  RUNNING: "warning",
  COMPLETED: "success",
  FAILED: "error"
};

export function StatusChip({
  status,
  label
}: {
  status: string;
  label?: string;
}) {
  return (
    <Chip
      size="small"
      color={statusMap[status] ?? "default"}
      label={label ?? status}
      variant={statusMap[status] === "default" ? "outlined" : "filled"}
    />
  );
}

