"use client";

import { Button, DialogActions, Stack, Typography } from "@mui/material";
import LocalPrintshopRoundedIcon from "@mui/icons-material/LocalPrintshopRounded";

export function ModalActionBar({
  canPrint,
  canSubmit,
  printing,
  quantity,
  onClose,
  onPrint
}: {
  canPrint: boolean;
  canSubmit: boolean;
  printing: boolean;
  quantity: number;
  onClose: () => void;
  onPrint: () => void;
}) {
  return (
    <DialogActions
      sx={{
        px: { xs: 2, md: 3 },
        py: 2,
        borderTop: "1px solid rgba(15, 23, 42, 0.08)",
        justifyContent: "space-between",
        alignItems: { xs: "stretch", md: "center" },
        flexDirection: { xs: "column", md: "row" },
        gap: 1.5
      }}
    >
      <Typography variant="body2" color="text.secondary" sx={{ maxWidth: 620 }}>
        {canPrint
          ? `${quantity} etiqueta${quantity > 1 ? "s" : ""} ${quantity > 1 ? "serao enviadas" : "sera enviada"} usando a mesma base visual do preview oficial.`
          : "Seu papel atual permite consultar o modelo, mas nao disparar impressao."}
      </Typography>

      <Stack direction="row" spacing={1.25}>
        <Button variant="outlined" onClick={onClose}>
          Cancelar
        </Button>
        <Button
          variant="contained"
          disabled={!canSubmit}
          startIcon={<LocalPrintshopRoundedIcon />}
          onClick={onPrint}
        >
          {printing ? "Imprimindo..." : "Imprimir"}
        </Button>
      </Stack>
    </DialogActions>
  );
}
