"use client";

import dynamic from "next/dynamic";
import type { BarcodeSymbolProps } from "./barcode-symbol-renderer";

const DynamicBarcodeSymbolRenderer = dynamic<BarcodeSymbolProps>(
  () => import("./barcode-symbol-renderer").then((module) => module.BarcodeSymbolRenderer),
  {
    ssr: false,
    loading: () => (
      <div
        aria-hidden="true"
        style={{
          width: "100%",
          height: "100%",
          background:
            "repeating-linear-gradient(90deg, #111827 0 2px, #ffffff 2px 5px)"
        }}
      />
    )
  }
);

export function BarcodeSymbol(props: BarcodeSymbolProps) {
  return <DynamicBarcodeSymbolRenderer {...props} />;
}
