"use client";

import Link from "next/link";
import { Box, Button, Card, Chip, Stack, Typography } from "@mui/material";
import OpenInNewRoundedIcon from "@mui/icons-material/OpenInNewRounded";
import LocalPrintshopRoundedIcon from "@mui/icons-material/LocalPrintshopRounded";
import type { TemplateListItem } from "../../lib/api";
import { StatusChip } from "../ui/status-chip";
import { getCategoryDefinition, type ModelCategory } from "../../lib/template-library";

const formatTemplateDate = (value: string) =>
  new Intl.DateTimeFormat("pt-BR", {
    day: "2-digit",
    month: "short"
  }).format(new Date(value));

export function TemplateModelCard({
  template,
  category,
  canEdit,
  onOpen
}: {
  template: TemplateListItem;
  category: ModelCategory;
  canEdit: boolean;
  onOpen: () => void;
}) {
  const categoryConfig = getCategoryDefinition(category);

  return (
    <Card
      sx={{
        display: "grid",
        gap: 2,
        p: 2.25,
        height: "100%"
      }}
    >
      <Box
        role="button"
        onClick={onOpen}
        sx={{
          cursor: "pointer",
          display: "grid",
          gap: 2,
          borderRadius: 3,
          p: 0.5
        }}
      >
        <Box
          sx={{
            borderRadius: 3,
            border: "1px solid rgba(15, 23, 42, 0.08)",
            background: `linear-gradient(145deg, ${categoryConfig.soft}, rgba(255,255,255,0.94))`,
            p: 2,
            minHeight: 180,
            display: "grid",
            alignContent: "space-between",
            gap: 2
          }}
        >
          <Typography
            variant="overline"
            sx={{ color: categoryConfig.accent, fontWeight: 800 }}
          >
            {categoryConfig.label}
          </Typography>

          <Box
            sx={{
              mx: "auto",
              width: "min(100%, 180px)",
              borderRadius: 2.5,
              overflow: "hidden",
              bgcolor: "#fff",
              boxShadow: "0 16px 28px rgba(15, 23, 42, 0.08)"
            }}
          >
            <Box sx={{ height: 14, bgcolor: categoryConfig.accent }} />
            <Stack spacing={1.1} sx={{ p: 1.5 }}>
              <Box sx={{ height: 16, borderRadius: 999, bgcolor: categoryConfig.soft }} />
              <Box sx={{ height: 10, borderRadius: 999, bgcolor: "rgba(15, 23, 42, 0.1)" }} />
              <Box
                sx={{
                  height: 10,
                  width: "70%",
                  borderRadius: 999,
                  bgcolor: "rgba(15, 23, 42, 0.1)"
                }}
              />
              <Box sx={{ height: 40, borderRadius: 1.5, bgcolor: "rgba(15, 23, 42, 0.08)" }} />
              <Stack direction="row" spacing={1}>
                <Box sx={{ flex: 1, height: 8, borderRadius: 999, bgcolor: "rgba(15, 23, 42, 0.08)" }} />
                <Box sx={{ width: 42, height: 8, borderRadius: 999, bgcolor: "rgba(15, 23, 42, 0.08)" }} />
              </Stack>
            </Stack>
          </Box>
        </Box>

        <Stack spacing={1.1}>
          <Box>
            <Typography variant="overline" color="text.secondary">
              Modelo operacional
            </Typography>
            <Typography variant="h6" component="h3">
              {template.name}
            </Typography>
            <Typography variant="body2" color="text.secondary">
              {categoryConfig.description}
            </Typography>
          </Box>

          <Stack direction="row" spacing={1} useFlexGap sx={{ flexWrap: "wrap" }}>
            <Chip size="small" variant="outlined" label={`v${template.currentVersion}`} />
            <StatusChip status={template.status} />
            {template.lastPublishedVersion ? (
              <Chip
                size="small"
                variant="outlined"
                color="primary"
                label={`publicado v${template.lastPublishedVersion}`}
              />
            ) : null}
          </Stack>

          <Stack spacing={0.4}>
            <Typography variant="body2" color="text.secondary">
              Responsavel base: {categoryConfig.defaultResponsible}
            </Typography>
            <Typography variant="body2" color="text.secondary">
              Atualizado em {formatTemplateDate(template.updatedAt)}
            </Typography>
          </Stack>
        </Stack>
      </Box>

      <Box
        sx={{
          borderTop: "1px solid rgba(15, 23, 42, 0.08)",
          pt: 2,
          display: "grid",
          gap: 1.5
        }}
      >
        <Typography variant="body2" color="text.secondary">
          Entre pelo fluxo rapido ou abra o mesmo layout no editor para ajustes livres.
        </Typography>

        <Stack direction={{ xs: "column", sm: "row" }} spacing={1.25}>
          <Button
            variant="contained"
            startIcon={<LocalPrintshopRoundedIcon />}
            onClick={onOpen}
          >
            Preencher e imprimir
          </Button>
          {canEdit ? (
            <Button
              component={Link}
              href={`/editor/${template.id}`}
              variant="outlined"
              startIcon={<OpenInNewRoundedIcon />}
            >
              Abrir no editor
            </Button>
          ) : null}
        </Stack>
      </Box>
    </Card>
  );
}
