"use client";

import Link from "next/link";
import { useCallback, useEffect, useMemo, useState } from "react";
import {
  Alert,
  Box,
  Button,
  Chip,
  MenuItem,
  Stack,
  Tab,
  Tabs,
  TextField,
  Typography
} from "@mui/material";
import AddRoundedIcon from "@mui/icons-material/AddRounded";
import { DashboardShell } from "../components/app/dashboard-shell";
import { SessionGuard } from "../components/app/session-guard";
import { TemplateModelCard } from "../components/templates/template-model-card";
import { TemplatePrintModal } from "../components/templates/template-print-modal";
import { PageSection } from "../components/ui/page-section";
import {
  fetchPrintProfiles,
  fetchPrinters,
  fetchTemplates,
  type PrintProfileItem,
  type PrinterItem,
  type TemplateListItem
} from "../lib/api";
import { sessionHasPermission, type ApiSession } from "../lib/session";
import {
  getCategoryDefinition,
  inferTemplateCategory,
  MODEL_CATEGORIES,
  type ModelCategory
} from "../lib/template-library";

type CategoryFilter = "all" | ModelCategory;

function TemplatesPageContent() {
  const [session, setSession] = useState<ApiSession | null>(null);
  const [templates, setTemplates] = useState<TemplateListItem[]>([]);
  const [printers, setPrinters] = useState<PrinterItem[]>([]);
  const [profiles, setProfiles] = useState<PrintProfileItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [routeLoading, setRouteLoading] = useState(false);
  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState("all");
  const [categoryFilter, setCategoryFilter] = useState<CategoryFilter>("all");
  const [selectedTemplate, setSelectedTemplate] = useState<TemplateListItem | null>(null);
  const [feedback, setFeedback] = useState<string | null>(null);
  const canViewTemplates = sessionHasPermission(session, "template.view");
  const canEditTemplates = sessionHasPermission(session, "template.edit");
  const canPrintTemplates = sessionHasPermission(session, "print-job.test");

  const loadTemplates = useCallback(
    async (activeSession: ApiSession) => {
      setLoading(true);
      try {
        const nextTemplates = await fetchTemplates(activeSession, {
          search: search || undefined,
          status: statusFilter === "all" ? undefined : statusFilter
        });
        setTemplates(nextTemplates);
      } finally {
        setLoading(false);
      }
    },
    [search, statusFilter]
  );

  useEffect(() => {
    if (!session || !canViewTemplates) {
      setLoading(false);
      return;
    }

    void loadTemplates(session);
  }, [canViewTemplates, loadTemplates, session]);

  useEffect(() => {
    if (!session || !canPrintTemplates) {
      setPrinters([]);
      setProfiles([]);
      return;
    }

    let active = true;
    setRouteLoading(true);

    void Promise.all([
      fetchPrinters(session, { active: "true" }),
      fetchPrintProfiles(session)
    ])
      .then(([nextPrinters, nextProfiles]) => {
        if (!active) return;
        setPrinters(nextPrinters);
        setProfiles(nextProfiles);
      })
      .finally(() => {
        if (!active) return;
        setRouteLoading(false);
      });

    return () => {
      active = false;
    };
  }, [canPrintTemplates, session]);

  const templatesWithCategory = useMemo(
    () =>
      templates.map((template) => ({
        ...template,
        resolvedCategory: inferTemplateCategory(template)
      })),
    [templates]
  );

  const categoryCounts = useMemo(() => {
    const counts = MODEL_CATEGORIES.reduce<Record<ModelCategory, number>>(
      (accumulator, category) => ({
        ...accumulator,
        [category]: 0
      }),
      {
        doces: 0,
        salgados: 0,
        bebidas: 0,
        refeicao: 0
      }
    );

    templatesWithCategory.forEach((template) => {
      counts[template.resolvedCategory] += 1;
    });

    return counts;
  }, [templatesWithCategory]);

  const visibleTemplates = useMemo(
    () =>
      templatesWithCategory.filter((template) =>
        categoryFilter === "all" ? true : template.resolvedCategory === categoryFilter
      ),
    [categoryFilter, templatesWithCategory]
  );

  const selectedCategory =
    selectedTemplate ? inferTemplateCategory(selectedTemplate) : null;

  return (
    <SessionGuard onSession={setSession}>
      <DashboardShell
        title="Biblioteca de Modelos"
        subtitle="Organize os modelos por categoria, entre no fluxo operacional rapido ou abra o mesmo layout no editor com uma base visual mais consistente."
        action={
          canEditTemplates ? (
            <Button
              component={Link}
              href="/editor/new"
              variant="contained"
              startIcon={<AddRoundedIcon />}
            >
              Novo template
            </Button>
          ) : null
        }
      >
        <Stack spacing={3}>
          {!canViewTemplates ? (
            <Alert severity="warning" variant="outlined">
              Seu papel atual nao possui acesso a biblioteca de templates.
            </Alert>
          ) : null}

          {feedback ? (
            <Alert severity="success" onClose={() => setFeedback(null)}>
              {feedback}
            </Alert>
          ) : null}

          {canViewTemplates ? (
            <>
              <PageSection
                title="Catalogo operacional"
                description="Pesquise, filtre o status e navegue pelas categorias sem perder o foco no fluxo rapido de impressao."
              >
                <Box
                  sx={{
                    display: "grid",
                    gridTemplateColumns: { xs: "1fr", md: "minmax(0, 1fr) 220px" },
                    gap: 2
                  }}
                >
                  <TextField
                    label="Buscar por nome ou slug"
                    value={search}
                    onChange={(event) => setSearch(event.target.value)}
                  />
                  <TextField
                    select
                    label="Status"
                    value={statusFilter}
                    onChange={(event) => setStatusFilter(event.target.value)}
                  >
                    <MenuItem value="all">Todos os status</MenuItem>
                    <MenuItem value="DRAFT">Draft</MenuItem>
                    <MenuItem value="IN_REVIEW">In review</MenuItem>
                    <MenuItem value="APPROVED">Approved</MenuItem>
                    <MenuItem value="PUBLISHED">Published</MenuItem>
                    <MenuItem value="ARCHIVED">Archived</MenuItem>
                  </TextField>
                </Box>
              </PageSection>

              <PageSection
                title="Modelos por categoria"
                description="A biblioteca funciona como area operacional de selecao. Escolha a categoria, revise o contexto e siga para preenchimento rapido."
              >
                <Stack spacing={2}>
                  <Tabs
                    value={categoryFilter}
                    onChange={(_, value: CategoryFilter) => setCategoryFilter(value)}
                    variant="scrollable"
                    scrollButtons="auto"
                    allowScrollButtonsMobile
                  >
                    <Tab value="all" label={`Todos (${templatesWithCategory.length})`} />
                    {MODEL_CATEGORIES.map((category) => (
                      <Tab
                        key={category}
                        value={category}
                        label={`${getCategoryDefinition(category).label} (${categoryCounts[category]})`}
                      />
                    ))}
                  </Tabs>

                  <Box
                    sx={{
                      display: "grid",
                      gridTemplateColumns: {
                        xs: "1fr",
                        md: "repeat(2, minmax(0, 1fr))",
                        xl: "repeat(4, minmax(0, 1fr))"
                      },
                      gap: 2
                    }}
                  >
                    {MODEL_CATEGORIES.map((category) => {
                      const config = getCategoryDefinition(category);
                      return (
                        <Box
                          key={category}
                          sx={{
                            p: 2,
                            borderRadius: 3,
                            border: "1px solid rgba(15, 23, 42, 0.08)",
                            background: config.soft
                          }}
                        >
                          <Stack spacing={1}>
                            <Typography variant="subtitle1" sx={{ color: config.accent, fontWeight: 700 }}>
                              {config.label}
                            </Typography>
                            <Typography variant="body2" color="text.secondary">
                              {config.description}
                            </Typography>
                            <Chip
                              size="small"
                              color="primary"
                              variant="outlined"
                              label={`Responsavel padrao: ${config.defaultResponsible}`}
                              sx={{ alignSelf: "flex-start", backgroundColor: "#fff" }}
                            />
                          </Stack>
                        </Box>
                      );
                    })}
                  </Box>
                </Stack>
              </PageSection>
            </>
          ) : null}

          {routeLoading ? (
            <Alert severity="info" variant="outlined">
              Preparando rota operacional de impressao...
            </Alert>
          ) : null}

          <PageSection
            title="Modelos disponiveis"
            description="Escolha um modelo para preencher e imprimir rapidamente, ou abra o mesmo documento no editor visual."
          >
            <Box
              sx={{
                display: "grid",
                gridTemplateColumns: {
                  xs: "1fr",
                  md: "repeat(2, minmax(0, 1fr))",
                  xl: "repeat(3, minmax(0, 1fr))"
                },
                gap: 2.25
              }}
            >
              {canViewTemplates && loading ? (
                <Typography color="text.secondary">Carregando templates...</Typography>
              ) : null}

              {canViewTemplates && !loading && visibleTemplates.length === 0 ? (
                <Alert severity="info" variant="outlined">
                  Nenhum template encontrado para os filtros atuais.
                </Alert>
              ) : null}

              {canViewTemplates &&
                visibleTemplates.map((template) => (
                  <TemplateModelCard
                    key={template.id}
                    template={template}
                    category={template.resolvedCategory}
                    canEdit={canEditTemplates}
                    onOpen={() => setSelectedTemplate(template)}
                  />
                ))}
            </Box>
          </PageSection>
        </Stack>

        <TemplatePrintModal
          open={Boolean(selectedTemplate)}
          template={selectedTemplate}
          category={selectedCategory}
          session={session}
          printers={printers}
          profiles={profiles}
          canPrint={canPrintTemplates}
          onClose={() => setSelectedTemplate(null)}
          onPrinted={(message) => setFeedback(message)}
        />
      </DashboardShell>
    </SessionGuard>
  );
}

export default function HomePage() {
  return <TemplatesPageContent />;
}
